      if (!hook) {
        throw new Error("expected reply_dispatch hook to be registered");
      }

      const run = hook(
        {
          ctx: { raw: "reply ctx" },
          runId: "run-1",
          sessionKey: "agent:test:session",
          inboundAudio: false,
          shouldRouteToOriginating: false,
          shouldSendToolSummaries: true,
          shouldSendFullToolDetails: false,
