import process from "node:process";
import type {
  SessionCatalogSession,
  SessionCatalogTranscriptItem,
  SessionsCatalogReadResult,
} from "openclaw/plugin-sdk/session-catalog";
import { sessionCatalogPaging } from "openclaw/plugin-sdk/session-catalog";
import {
  isRecord,
  normalizeBoundedOptionalString as optionalPiString,
} from "openclaw/plugin-sdk/string-coerce-runtime";
import { truncateUtf16Safe } from "openclaw/plugin-sdk/text-utility-runtime";
import {
  PI_LOCAL_SESSION_HOST_ID as LOCAL_HOST_ID,
  PI_SESSION_ID_PATTERN as SESSION_ID_PATTERN,
} from "./pi-session-catalog-shared.js";
import { listPiSummaryPage, readPiSessionById } from "./pi-session-store.js";
import { parsePiSessionTimestampMs } from "./pi-session-timestamp.js";

const MAX_SEARCH_LENGTH = 500;

type PiSessionPage = { sessions: SessionCatalogSession[]; nextCursor?: string };

export const isExactPiSessionCursor = sessionCatalogPaging.isExactCursor;

function textFromContent(content: unknown): string {
  if (typeof content === "string") {
    return content;
  }
  if (!Array.isArray(content)) {
    return "";
  }
  return content
    .flatMap((part) => {
      if (!isRecord(part)) {
        return [];
      }
      if (part.type === "text" && typeof part.text === "string") {
        return [part.text];
      }
      if (part.type === "image") {
        const mimeType = optionalPiString(part.mimeType, 128);
        return [mimeType ? `[image: ${mimeType}]` : "[image]"];
      }
      return [];
    })
    .join("\n");
}

const PI_PARAMETER_MESSAGES = {
  listNotObject: "Pi session list parameters must be an object",
  unknownListParameter: (key: string) => `unknown Pi session list parameter: ${key}`,
  invalidSearchTerm: "searchTerm is invalid",
  readNotObject: "Pi session read parameters must be an object",
  unknownReadParameter: (key: string) => `unknown Pi session read parameter: ${key}`,
  invalidThreadId: "threadId is invalid",
};

export async function listLocalPiSessionPage(value?: unknown): Promise<PiSessionPage> {
  const params = sessionCatalogPaging.parseListParams(value, {
    searchMaxLength: MAX_SEARCH_LENGTH,
    messages: PI_PARAMETER_MESSAGES,
  });
  const offset = sessionCatalogPaging.decodeCursor(params.cursor);
  const { summaries, hasMore } = await listPiSummaryPage(process.env, {
    offset,
    limit: params.limit,
    ...(params.searchTerm ? { searchTerm: params.searchTerm } : {}),
  });
  const page = summaries.map(({ file: _file, version: _version, ...session }) => session);
  return {
    sessions: page,
    ...(hasMore ? { nextCursor: sessionCatalogPaging.encodeCursor(offset + page.length) } : {}),
  };
}

function isoTimestamp(
  message: Record<string, unknown>,
  entry: Record<string, unknown>,
): string | undefined {
  const value =
    parsePiSessionTimestampMs(message.timestamp) ?? parsePiSessionTimestampMs(entry.timestamp);
  if (value === undefined) {
    return undefined;
  }
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? undefined : date.toISOString();
}

function jsonText(value: unknown, maxLength = 20_000): string | undefined {
  try {
    const text = JSON.stringify(value);
    return text.length > maxLength ? `${truncateUtf16Safe(text, maxLength)}…` : text;
  } catch {
    return undefined;
  }
}

function activePiEntries(entries: Record<string, unknown>[]): Record<string, unknown>[] {
  const header = entries[0];
  const version =
    header?.type === "session" && typeof header.version === "number" ? header.version : 1;
  if (version < 2) {
    return entries.slice(1);
  }
  const body = entries.filter(
    (entry) => entry.type !== "session" && optionalPiString(entry.id, 256),
  );
  const byId = new Map(body.map((entry) => [String(entry.id), entry]));
  const active: Record<string, unknown>[] = [];
  let current = body.at(-1);
  const visited = new Set<string>();
  while (current) {
    const id = String(current.id);
    if (visited.has(id)) {
      break;
    }
    visited.add(id);
    active.push(current);
    const parentId = optionalPiString(current.parentId, 256);
    current = parentId ? byId.get(parentId) : undefined;
  }
  return active.toReversed();
}

function piMessageItems(entry: Record<string, unknown>): SessionCatalogTranscriptItem[] {
  if (!isRecord(entry.message)) {
    return [];
  }
  const message = entry.message;
  const role = message.role;
  const id = optionalPiString(entry.id, 256);
  const timestamp = isoTimestamp(message, entry);
  const model = optionalPiString(message.model, 256);
  const provider = optionalPiString(message.provider, 256);
  const modelRef = provider && model ? `${provider}/${model}` : model;
  const common = {
    ...(id ? { id } : {}),
    ...(timestamp ? { timestamp } : {}),
    ...(modelRef ? { model: modelRef } : {}),
  };
  if (role === "user") {
    const text = textFromContent(message.content);
    return text ? [{ ...common, type: "userMessage", text }] : [];
  }
  if (role === "toolResult") {
    const toolName = optionalPiString(message.toolName, 256);
    const text = textFromContent(message.content);
    return [{ ...common, type: "toolResult", text: toolName ? `${toolName}\n${text}` : text }];
  }
  if (role === "bashExecution") {
    const command = optionalPiString(message.command, 4_096) ?? "bash";
    const output = typeof message.output === "string" ? message.output : "";
    const status =
      message.cancelled === true
        ? "command cancelled"
        : typeof message.exitCode === "number" && message.exitCode !== 0
          ? `command exited with code ${String(message.exitCode)}`
          : "";
    return [
      { ...common, type: "toolCall", text: `bash\n${command}` },
      {
        ...common,
        ...(id ? { id: `${id}:result` } : {}),
        type: "toolResult",
        text: [output, status].filter(Boolean).join("\n\n"),
      },
    ];
  }
  if (role === "custom" || role === "hookMessage") {
    if (message.display !== true) {
      return [];
    }
    const customType = optionalPiString(message.customType, 256);
    const text = textFromContent(message.content);
    return text
      ? [{ ...common, type: "other", text: customType ? `${customType}\n${text}` : text }]
      : [];
  }
  if (role !== "assistant" || !Array.isArray(message.content)) {
    return [];
  }
  return message.content.flatMap((part, index): SessionCatalogTranscriptItem[] => {
    if (!isRecord(part)) {
      return [];
    }
    const partCommon = { ...common, ...(id ? { id: `${id}:${String(index)}` } : {}) };
    if (part.type === "text" && typeof part.text === "string") {
      return [{ ...partCommon, type: "agentMessage", text: part.text }];
    }
    if (part.type === "thinking" && typeof part.thinking === "string") {
      return [{ ...partCommon, type: "reasoning", text: part.thinking }];
    }
    if (part.type === "toolCall") {
      const name = optionalPiString(part.name, 256) ?? "tool";
      const args = jsonText(part.arguments);
      return [{ ...partCommon, type: "toolCall", text: args ? `${name}\n${args}` : name }];
    }
    return [];
  });
}

function piTranscriptItems(entries: Record<string, unknown>[]): SessionCatalogTranscriptItem[] {
  return activePiEntries(entries).flatMap((entry): SessionCatalogTranscriptItem[] => {
    if (entry.type === "message") {
      return piMessageItems(entry);
    }
    const id = optionalPiString(entry.id, 256);
    const timestamp = optionalPiString(entry.timestamp, 128);
    const common = { ...(id ? { id } : {}), ...(timestamp ? { timestamp } : {}) };
    if (entry.type === "compaction" && typeof entry.summary === "string") {
      return [{ ...common, type: "other", text: entry.summary }];
    }
    if (entry.type === "branch_summary" && typeof entry.summary === "string") {
      return [{ ...common, type: "other", text: entry.summary }];
    }
    if (entry.type === "custom_message" && entry.display === true) {
      const text = textFromContent(entry.content);
      return text ? [{ ...common, type: "other", text }] : [];
    }
    return [];
  });
}

export async function readLocalPiTranscriptPage(
  value: unknown,
): Promise<SessionsCatalogReadResult> {
  const params = sessionCatalogPaging.parseReadParams(value, {
    threadIdMaxLength: 256,
    threadIdPattern: SESSION_ID_PATTERN,
    messages: PI_PARAMETER_MESSAGES,
  });
  const offset = sessionCatalogPaging.decodeCursor(params.cursor);
  const items = piTranscriptItems(await readPiSessionById(params.threadId, process.env));
  const page = sessionCatalogPaging.boundTranscriptPage(items, params.limit, offset);
  return {
    hostId: LOCAL_HOST_ID,
    label: "Local Pi",
    threadId: params.threadId,
    ...page,
  };
}

import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { piSessionStore } from "./pi-session-paths.js";

const temporaryDirectories: string[] = [];

afterEach(async () => {
  await Promise.all(
    temporaryDirectories.splice(0).map(async (directory) => {
      await fs.rm(directory, { recursive: true, force: true });
    }),
  );
});

describe("Pi session paths", () => {
  it("rejects Windows drive-less rooted session paths", () => {
    const originalPlatform = process.platform;
    try {
      Object.defineProperty(process, "platform", { configurable: true, value: "win32" });
      expect(() => piSessionStore({ PI_CODING_AGENT_SESSION_DIR: "\\sessions" })).toThrow(
        "absolute or home-relative",
      );
      expect(() => piSessionStore({ PI_CODING_AGENT_SESSION_DIR: "C:\\sessions" })).not.toThrow();
      expect(() =>
        piSessionStore({ PI_CODING_AGENT_SESSION_DIR: "\\\\server\\share\\sessions" }),
      ).not.toThrow();
    } finally {
      Object.defineProperty(process, "platform", { configurable: true, value: originalPlatform });
    }
  });

  it("trims the configured Pi agent directory", () => {
    const agentDir = path.join(os.tmpdir(), "pi-agent");
    expect(piSessionStore({ PI_CODING_AGENT_DIR: `  ${agentDir}  ` })).toEqual({
      root: path.join(agentDir, "sessions"),
      flat: false,
      usesProcessHomeFallback: false,
    });
  });

  it("resolves relative project and global session directories like Pi", async () => {
    const projectDirectory = await fs.mkdtemp(path.join(os.tmpdir(), "openclaw-pi-project-"));
    const agentDirectory = await fs.mkdtemp(path.join(os.tmpdir(), "openclaw-pi-agent-"));
    temporaryDirectories.push(projectDirectory, agentDirectory);
    await fs.mkdir(path.join(projectDirectory, ".pi"), { recursive: true });
    await fs.writeFile(
      path.join(projectDirectory, ".pi", "settings.json"),
      `${JSON.stringify({ sessionDir: "sessions" })}\n`,
    );
    const env = {
      HOME: projectDirectory,
      USERPROFILE: projectDirectory,
      PI_CODING_AGENT_DIR: agentDirectory,
    };

    expect(piSessionStore(env, projectDirectory)).toEqual({
      root: path.join(projectDirectory, ".pi", "sessions"),
      flat: true,
      usesProcessHomeFallback: false,
    });

    await fs.rm(path.join(projectDirectory, ".pi", "settings.json"));
    await fs.writeFile(
      path.join(agentDirectory, "settings.json"),
      `${JSON.stringify({ sessionDir: "custom-sessions" })}\n`,
    );
    expect(piSessionStore(env, projectDirectory)).toEqual({
      root: path.join(agentDirectory, "custom-sessions"),
      flat: true,
      usesProcessHomeFallback: false,
    });
  });

  it("marks only the default home-derived store as a process-HOME fallback", () => {
    const home = path.join(os.tmpdir(), "pi-home");
    expect(piSessionStore({ HOME: home }).usesProcessHomeFallback).toBe(true);
    expect(
      piSessionStore({ HOME: home, PI_CODING_AGENT_SESSION_DIR: path.join(home, "sessions") })
        .usesProcessHomeFallback,
    ).toBe(false);
  });
});

import { readFileSync, statSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import {
  isRecord,
  normalizeBoundedOptionalString as readBoundedString,
} from "openclaw/plugin-sdk/string-coerce-runtime";

function piHome(env: NodeJS.ProcessEnv): string {
  const configured = process.platform === "win32" ? env.USERPROFILE?.trim() : env.HOME?.trim();
  return configured || os.homedir();
}

function isPiSessionCatalogPathAbsolute(
  value: string,
  platform: NodeJS.Platform = process.platform,
): boolean {
  if (platform !== "win32") {
    return path.posix.isAbsolute(value);
  }
  const root = path.win32.parse(value).root;
  return path.win32.isAbsolute(value) && root !== "\\" && root !== "/";
}

function resolveConfiguredPath(
  value: string,
  env: NodeJS.ProcessEnv,
  relativeBase?: string,
): string {
  const home = piHome(env);
  let resolved = value;
  if (value === "~") {
    resolved = home;
  }
  if (value.startsWith("~/") || value.startsWith("~\\")) {
    resolved = path.join(home, value.slice(2));
  }
  if (!isPiSessionCatalogPathAbsolute(resolved)) {
    if (relativeBase) {
      return path.resolve(relativeBase, resolved);
    }
    throw new Error("Pi session catalog requires absolute or home-relative storage paths");
  }
  return path.resolve(resolved);
}

function settingsSessionDir(file: string): string | undefined {
  try {
    const value = JSON.parse(readFileSync(file, "utf8")) as unknown;
    return isRecord(value) ? readBoundedString(value.sessionDir, 4_096) : undefined;
  } catch {
    return undefined;
  }
}

export function piSessionStore(
  env: NodeJS.ProcessEnv,
  cwd = process.cwd(),
): { root: string; flat: boolean; usesProcessHomeFallback: boolean } {
  const customSessionDir = env.PI_CODING_AGENT_SESSION_DIR?.trim();
  if (customSessionDir) {
    return {
      root: resolveConfiguredPath(customSessionDir, env),
      flat: true,
      usesProcessHomeFallback: false,
    };
  }
  const home = piHome(env);
  const customAgentDir = env.PI_CODING_AGENT_DIR?.trim();
  const agentDir = customAgentDir
    ? resolveConfiguredPath(customAgentDir, env)
    : path.join(home, ".pi", "agent");
  const projectSessionDir = settingsSessionDir(path.join(cwd, ".pi", "settings.json"));
  if (projectSessionDir) {
    return {
      root: resolveConfiguredPath(projectSessionDir, env, path.join(cwd, ".pi")),
      flat: true,
      usesProcessHomeFallback: false,
    };
  }
  const globalSessionDir = settingsSessionDir(path.join(agentDir, "settings.json"));
  if (globalSessionDir) {
    return {
      root: resolveConfiguredPath(globalSessionDir, env, agentDir),
      flat: true,
      usesProcessHomeFallback: false,
    };
  }
  return {
    root: path.join(agentDir, "sessions"),
    flat: false,
    usesProcessHomeFallback: !customAgentDir,
  };
}

/** Store root scanned by pi-acp@0.0.26 when resolving a native session id. */
export function piAcpSessionStoreRoot(env: NodeJS.ProcessEnv): string | undefined {
  const configuredAgentDir = env.PI_CODING_AGENT_DIR?.trim();
  // Deliberately stricter than piSessionStore(): pi-acp's session lookup reads
  // PI_CODING_AGENT_DIR raw, with no `~` expansion (getPiAgentDir, dist/index.js:1044,
  // reached via findPiSessionFile -> listPiSessions). Expanding `~` here would advertise
  // Continue on sessions pi-acp then fails to resolve with "Unknown sessionId".
  if (configuredAgentDir && !isPiSessionCatalogPathAbsolute(configuredAgentDir)) {
    return undefined;
  }
  const agentDir = configuredAgentDir
    ? path.resolve(configuredAgentDir)
    : path.join(piHome(env), ".pi", "agent");
  return path.join(agentDir, "sessions");
}

export function piSessionStoreAvailable(
  env: NodeJS.ProcessEnv,
  store?: ReturnType<typeof piSessionStore>,
): boolean {
  try {
    return statSync((store ?? piSessionStore(env)).root).isDirectory();
  } catch {
    return false;
  }
}

import { createReadStream } from "node:fs";
import fs from "node:fs/promises";
import path from "node:path";
import { runTasksWithConcurrency } from "openclaw/plugin-sdk/concurrency-runtime";
import { isPathStrictlyInside } from "openclaw/plugin-sdk/file-access-runtime";
import type { SessionCatalogSession } from "openclaw/plugin-sdk/session-catalog";
import {
  isRecord,
  normalizeBoundedOptionalString as readBoundedString,
} from "openclaw/plugin-sdk/string-coerce-runtime";
import { piAcpSessionStoreRoot, piSessionStore } from "./pi-session-paths.js";
import { parsePiSessionTimestampMs } from "./pi-session-timestamp.js";

const MAX_DISCOVERY_FILES = 10_000;
const SUMMARY_SCAN_BATCH_SIZE = 100;
const MAX_SUMMARY_CACHE_ENTRIES = 256;
const MAX_SESSION_BYTES = 32 * 1024 * 1024;
const MAX_SUMMARY_LINE_BYTES = 1024 * 1024;
const APPEND_PROOF_EDGE_BYTES = 64 * 1024;
const IO_CONCURRENCY = 8;
const PI_FILE_CANDIDATE_CACHE_TTL_MS = 32_000;
const PI_FILE_CANDIDATE_CACHE_MAX_ENTRIES = 8;
const SESSION_ID_PATTERN = /^(?!-)[A-Za-z0-9._:-]{1,256}$/u;

type PiSessionSummary = SessionCatalogSession & { file: string; version: number };

type PiFileCandidate = {
  file: string;
  storeRoot: string;
  identity: string;
  mtimeMs: number;
  size: number;
  resumable: boolean;
};

type PiSummaryScanState = {
  header?: Record<string, unknown>;
  name?: string;
  firstMessage?: string;
  pending: Buffer;
  discarding: boolean;
  invalid: boolean;
};

type CachedSummary = PiFileCandidate & {
  summary?: PiSessionSummary;
  scanState: PiSummaryScanState;
  appendProof: { head: Buffer; tail: Buffer };
};

type PiFileCandidateCacheEntry = {
  expiresAt: number;
  candidates: Promise<PiFileCandidate[]>;
};

// Pi owns session-file mutation. The bounded cache resumes append-only metadata
// scans, avoiding a full reread every time an active transcript grows.
const summaryCache = new Map<string, CachedSummary>();
const threadFileCache = new Map<string, string>();
// Candidate snapshots are valid for one session-root/ACP-root identity for 32s, just beyond stable
// polling. Root changes or expiry re-walk; rejected scans are removed so transient I/O recovers.
// Keeping this bounded avoids rescanning every file each poll without retaining obsolete stores.
const piFileCandidateCache = new Map<string, PiFileCandidateCacheEntry>();

function threadCacheKey(storeRoot: string, threadId: string): string {
  return `${storeRoot}\0${threadId}`;
}

function forgetCachedSummary(file: string): void {
  const cached = summaryCache.get(file);
  const threadId = cached?.summary?.threadId;
  if (cached && threadId) {
    const key = threadCacheKey(cached.storeRoot, threadId);
    if (threadFileCache.get(key) === file) {
      threadFileCache.delete(key);
    }
  }
  summaryCache.delete(file);
}

function cacheSummary(file: string, value: CachedSummary): void {
  forgetCachedSummary(file);
  summaryCache.set(file, value);
  while (summaryCache.size > MAX_SUMMARY_CACHE_ENTRIES) {
    const oldest = summaryCache.keys().next().value;
    if (typeof oldest !== "string") {
      break;
    }
    forgetCachedSummary(oldest);
  }
}

async function discoverPiSessionFiles(
  env: NodeJS.ProcessEnv,
): Promise<{ root: string; files: string[] }> {
  const store = piSessionStore(env);
  const resolvedRoot = await realpathOrResolve(store.root);
  let entries: Array<import("node:fs").Dirent>;
  try {
    entries = await fs.readdir(resolvedRoot, { withFileTypes: true });
  } catch {
    return { root: store.root, files: [] };
  }
  if (store.flat) {
    return {
      root: store.root,
      files: entries
        .filter((entry) => entry.isFile() && entry.name.endsWith(".jsonl"))
        .slice(0, MAX_DISCOVERY_FILES)
        .map((entry) => path.join(resolvedRoot, entry.name)),
    };
  }
  const files: string[] = [];
  for (const entry of entries) {
    if (!entry.isDirectory() || files.length >= MAX_DISCOVERY_FILES) {
      continue;
    }
    const directory = path.join(resolvedRoot, entry.name);
    let children: Array<import("node:fs").Dirent>;
    try {
      children = await fs.readdir(directory, { withFileTypes: true });
    } catch {
      continue;
    }
    for (const child of children) {
      if (child.isFile() && child.name.endsWith(".jsonl")) {
        files.push(path.join(directory, child.name));
        if (files.length >= MAX_DISCOVERY_FILES) {
          break;
        }
      }
    }
  }
  return { root: store.root, files };
}

async function realpathOrResolve(value: string): Promise<string> {
  try {
    return await fs.realpath(value);
  } catch {
    return path.resolve(value);
  }
}

async function scanPiFileCandidates(env: NodeJS.ProcessEnv): Promise<PiFileCandidate[]> {
  const { root, files } = await discoverPiSessionFiles(env);
  const configuredAcpRoot = piAcpSessionStoreRoot(env);
  const acpRoot = configuredAcpRoot ? await realpathOrResolve(configuredAcpRoot) : undefined;
  const { results: candidates } = await runTasksWithConcurrency({
    tasks: files.map((file) => async () => {
      try {
        const stats = await fs.stat(file);
        return stats.isFile()
          ? {
              file,
              storeRoot: root,
              identity: `${String(stats.dev)}:${String(stats.ino)}:${String(stats.birthtimeMs)}`,
              mtimeMs: stats.mtimeMs,
              size: stats.size,
              resumable: acpRoot ? isPathStrictlyInside(acpRoot, file) : false,
            }
          : undefined;
      } catch {
        return undefined;
      }
    }),
    limit: IO_CONCURRENCY,
    throwOnError: true,
  });
  return candidates
    .filter((candidate): candidate is PiFileCandidate => candidate !== undefined)
    .toSorted((left, right) => right.mtimeMs - left.mtimeMs);
}

async function piFileCandidates(env: NodeJS.ProcessEnv): Promise<PiFileCandidate[]> {
  const store = piSessionStore(env);
  const key = `${store.root}\0${store.flat}\0${piAcpSessionStoreRoot(env) ?? ""}`;
  const cached = piFileCandidateCache.get(key);
  if (cached && cached.expiresAt > Date.now()) {
    piFileCandidateCache.delete(key);
    piFileCandidateCache.set(key, cached);
    return await cached.candidates;
  }
  if (cached) {
    piFileCandidateCache.delete(key);
  }
  const candidates = scanPiFileCandidates(env);
  const entry = { expiresAt: Date.now() + PI_FILE_CANDIDATE_CACHE_TTL_MS, candidates };
  piFileCandidateCache.set(key, entry);
  while (piFileCandidateCache.size > PI_FILE_CANDIDATE_CACHE_MAX_ENTRIES) {
    const oldest = piFileCandidateCache.keys().next();
    if (oldest.done) {
      break;
    }
    piFileCandidateCache.delete(oldest.value);
  }
  try {
    return await candidates;
  } catch (error) {
    if (piFileCandidateCache.get(key) === entry) {
      piFileCandidateCache.delete(key);
    }
    throw error;
  }
}

function parsePiJsonLines(content: string): Record<string, unknown>[] {
  return content.split(/\r?\n/u).flatMap((line) => {
    if (!line.trim()) {
      return [];
    }
    try {
      const value = JSON.parse(line) as unknown;
      return isRecord(value) ? [value] : [];
    } catch {
      return [];
    }
  });
}

function textFromContent(content: unknown): string {
  if (typeof content === "string") {
    return content;
  }
  if (!Array.isArray(content)) {
    return "";
  }
  return content
    .flatMap((part) =>
      isRecord(part) && part.type === "text" && typeof part.text === "string" ? [part.text] : [],
    )
    .join("\n");
}

function processSummaryLine(state: PiSummaryScanState, line: Buffer): void {
  const content = line.at(-1) === 0x0d ? line.subarray(0, -1) : line;
  const entry = parsePiJsonLines(content.toString("utf8"))[0];
  if (!entry) {
    return;
  }
  if (!state.header) {
    if (entry.type !== "session") {
      state.invalid = true;
      return;
    }
    state.header = entry;
    return;
  }
  if (entry.type === "session_info") {
    // Latest metadata wins, including an explicit empty-name clear.
    state.name = readBoundedString(entry.name, 1_000);
  } else if (
    !state.firstMessage &&
    entry.type === "message" &&
    isRecord(entry.message) &&
    entry.message.role === "user"
  ) {
    state.firstMessage = readBoundedString(textFromContent(entry.message.content), 1_000);
  }
}

function appendSummaryBytes(state: PiSummaryScanState, bytes: Buffer): void {
  if (state.discarding || bytes.length === 0) {
    return;
  }
  if (state.pending.length + bytes.length > MAX_SUMMARY_LINE_BYTES) {
    state.pending = Buffer.alloc(0);
    state.discarding = true;
    return;
  }
  state.pending =
    state.pending.length === 0 ? Buffer.from(bytes) : Buffer.concat([state.pending, bytes]);
}

async function scanSummaryAppend(
  candidate: PiFileCandidate,
  start: number,
  state: PiSummaryScanState,
): Promise<void> {
  if (start >= candidate.size || state.invalid) {
    return;
  }
  const stream = createReadStream(candidate.file, { start, end: candidate.size - 1 });
  for await (const value of stream) {
    const chunk = Buffer.isBuffer(value) ? value : Buffer.from(value);
    let offset = 0;
    while (offset < chunk.length) {
      const newline = chunk.indexOf(0x0a, offset);
      const end = newline < 0 ? chunk.length : newline;
      appendSummaryBytes(state, chunk.subarray(offset, end));
      if (newline < 0) {
        break;
      }
      if (!state.discarding) {
        processSummaryLine(state, state.pending);
      }
      state.pending = Buffer.alloc(0);
      state.discarding = false;
      if (state.invalid) {
        return;
      }
      offset = newline + 1;
    }
  }
}

async function readAppendProof(
  file: string,
  size: number,
): Promise<{ head: Buffer; tail: Buffer }> {
  const length = Math.min(size, APPEND_PROOF_EDGE_BYTES);
  if (length === 0) {
    return { head: Buffer.alloc(0), tail: Buffer.alloc(0) };
  }
  const handle = await fs.open(file, "r");
  try {
    const head = Buffer.alloc(length);
    const tail = Buffer.alloc(length);
    const [headRead, tailRead] = await Promise.all([
      handle.read(head, 0, length, 0),
      handle.read(tail, 0, length, size - length),
    ]);
    return {
      head: head.subarray(0, headRead.bytesRead),
      tail: tail.subarray(0, tailRead.bytesRead),
    };
  } finally {
    await handle.close();
  }
}

async function cachedPrefixIsUnchanged(candidate: PiFileCandidate, cached: CachedSummary) {
  if (cached.identity !== candidate.identity || cached.size >= candidate.size) {
    return false;
  }
  // Pi persists established sessions with appendFileSync. Its in-place rewrite
  // paths (notably version migration) rewrite the header, so the head proof
  // rejects them; the tail proof rejects truncation before later growth.
  const current = await readAppendProof(candidate.file, cached.size);
  return (
    current.head.equals(cached.appendProof.head) && current.tail.equals(cached.appendProof.tail)
  );
}

async function readPiSessionSummary(
  candidate: PiFileCandidate,
): Promise<PiSessionSummary | undefined> {
  const cached = summaryCache.get(candidate.file);
  if (cached?.mtimeMs === candidate.mtimeMs && cached.size === candidate.size) {
    summaryCache.delete(candidate.file);
    summaryCache.set(candidate.file, cached);
    return cached.summary
      ? { ...cached.summary, canContinue: candidate.resumable }
      : cached.summary;
  }
  let summary: PiSessionSummary | undefined;
  let scanState: PiSummaryScanState;
  let appendProof: CachedSummary["appendProof"];
  try {
    // Pi normally appends JSONL. Resume only when bounded edge proofs show the
    // previously indexed prefix survived; rewrites rebuild from byte zero.
    const resumable =
      cached && (await cachedPrefixIsUnchanged(candidate, cached)) ? cached : undefined;
    scanState = resumable
      ? {
          ...resumable.scanState,
          pending: Buffer.from(resumable.scanState.pending),
        }
      : {
          pending: Buffer.alloc(0),
          discarding: false,
          invalid: false,
        };
    await scanSummaryAppend(candidate, resumable?.size ?? 0, scanState);
    appendProof = await readAppendProof(candidate.file, candidate.size);
    // A complete final record is valid without a newline. Project it from a
    // clone so later appends can still finish the cached pending line once.
    const projectedState = { ...scanState, pending: Buffer.from(scanState.pending) };
    if (!projectedState.discarding && projectedState.pending.length > 0) {
      processSummaryLine(projectedState, projectedState.pending);
    }
    const { header, name, firstMessage } = projectedState;
    const version =
      header?.type === "session" && typeof header.version === "number" ? header.version : 1;
    const threadId = header?.type === "session" ? readBoundedString(header.id, 256) : undefined;
    if (header && threadId && SESSION_ID_PATTERN.test(threadId)) {
      const cwd = readBoundedString(header.cwd, 4_096);
      const createdAt = parsePiSessionTimestampMs(header.timestamp);
      summary = {
        file: candidate.file,
        version,
        threadId,
        ...(name || firstMessage ? { name: name ?? firstMessage } : {}),
        ...(cwd ? { cwd } : {}),
        status: "stored",
        ...(createdAt !== undefined ? { createdAt } : {}),
        updatedAt: candidate.mtimeMs,
        recencyAt: candidate.mtimeMs,
        source: "pi-cli",
        modelProvider: "pi",
        archived: false,
        canContinue: candidate.resumable,
        canArchive: false,
      };
    }
  } catch {
    // Permissions and concurrent file replacement are retryable. Preserve the
    // last good index instead of poisoning future append scans.
    return cached?.summary;
  }
  if (cached?.summary?.threadId && cached.summary.threadId !== summary?.threadId) {
    threadFileCache.delete(threadCacheKey(cached.storeRoot, cached.summary.threadId));
  }
  cacheSummary(candidate.file, { ...candidate, summary, scanState, appendProof });
  if (summary) {
    threadFileCache.set(threadCacheKey(candidate.storeRoot, summary.threadId), candidate.file);
  }
  return summary;
}

function summaryMatches(summary: PiSessionSummary, needle?: string): boolean {
  if (!needle) {
    return true;
  }
  return [summary.threadId, summary.name, summary.cwd].some((field) =>
    field?.toLocaleLowerCase().includes(needle),
  );
}

export async function listPiSummaryPage(
  env: NodeJS.ProcessEnv,
  params: { offset: number; limit: number; searchTerm?: string },
): Promise<{ summaries: PiSessionSummary[]; hasMore: boolean }> {
  const candidates = await piFileCandidates(env);
  const activeFiles = new Set(candidates.map((candidate) => candidate.file));
  for (const file of summaryCache.keys()) {
    if (!activeFiles.has(file)) {
      forgetCachedSummary(file);
    }
  }
  const target = params.offset + params.limit + 1;
  const matches: PiSessionSummary[] = [];
  const needle = params.searchTerm?.toLocaleLowerCase();
  for (
    let index = 0;
    index < candidates.length && matches.length < target;
    index += SUMMARY_SCAN_BATCH_SIZE
  ) {
    const batch = candidates.slice(index, index + SUMMARY_SCAN_BATCH_SIZE);
    const { results: summaries } = await runTasksWithConcurrency({
      tasks: batch.map((candidate) => () => readPiSessionSummary(candidate)),
      limit: IO_CONCURRENCY,
      throwOnError: true,
    });
    for (const summary of summaries) {
      if (summary && summaryMatches(summary, needle)) {
        matches.push(summary);
        if (matches.length >= target) {
          break;
        }
      }
    }
  }
  return {
    summaries: matches.slice(params.offset, params.offset + params.limit),
    hasMore: matches.length > params.offset + params.limit,
  };
}

async function findPiSummary(
  threadId: string,
  env: NodeJS.ProcessEnv,
): Promise<PiSessionSummary | undefined> {
  const candidates = await piFileCandidates(env);
  for (let index = 0; index < candidates.length; index += SUMMARY_SCAN_BATCH_SIZE) {
    const { results: summaries } = await runTasksWithConcurrency({
      tasks: candidates
        .slice(index, index + SUMMARY_SCAN_BATCH_SIZE)
        .map((candidate) => () => readPiSessionSummary(candidate)),
      limit: IO_CONCURRENCY,
      throwOnError: true,
    });
    const match = summaries.find((summary) => summary?.threadId === threadId);
    if (match) {
      return match;
    }
  }
  return undefined;
}

export async function readPiSessionFileBaseline(
  threadId: string,
  env: NodeJS.ProcessEnv,
): Promise<
  | {
      filePath: string;
      offset: number;
    }
  | undefined
> {
  const summary = await findPiSummary(threadId, env);
  if (!summary?.canContinue || summary.version < 3) {
    return undefined;
  }
  try {
    const stats = await fs.stat(summary.file);
    return stats.isFile() ? { filePath: summary.file, offset: stats.size } : undefined;
  } catch {
    return undefined;
  }
}

export async function readPiSessionById(
  threadId: string,
  env: NodeJS.ProcessEnv,
): Promise<Record<string, unknown>[]> {
  const cacheKey = threadCacheKey(piSessionStore(env).root, threadId);
  let file = threadFileCache.get(cacheKey);
  for (let attempt = 0; attempt < 2; attempt += 1) {
    if (!file) {
      file = (await findPiSummary(threadId, env))?.file;
    }
    if (!file) {
      throw new Error("Pi session was not found");
    }
    try {
      const stats = await fs.stat(file);
      if (!stats.isFile()) {
        throw new Error("Pi session is not a file");
      }
      if (stats.size > MAX_SESSION_BYTES) {
        throw new RangeError("Pi session exceeds the 32 MiB read safety limit");
      }
      const entries = parsePiJsonLines(await fs.readFile(file, "utf8"));
      if (entries[0]?.type === "session" && entries[0].id === threadId) {
        return entries;
      }
    } catch (error) {
      if (error instanceof RangeError) {
        throw error;
      }
      if (attempt > 0) {
        throw new Error("Pi session is unavailable", { cause: error });
      }
    }
    // The cached path can disappear when Pi replaces or prunes a session file.
    threadFileCache.delete(cacheKey);
    file = undefined;
  }
  throw new Error("Pi session changed during read");
}

