    const control = runtime.setMode({ handle, mode: "plan" });
    await Promise.resolve();
    expect(setMode).not.toHaveBeenCalled();
    releaseRetirement();

    await turn;
    await control;
    expect(setMode).toHaveBeenCalledTimes(1);
    expect(leaseStore.store.save).toHaveBeenCalledTimes(2);
