        ...f.runtimeOptions,
        openclawLegacyBareSessionKeys: new Set([resource]),
      });
      let adopted: Awaited<ReturnType<AcpxRuntime["ensureSession"]>> | undefined;
      try {
        await expect(
          runtime
            .ensureSession({ ...target, agent: "fixture", mode: "persistent" })
            .then((handle) => {
              adopted = handle;
